#!/usr/bin/env python3
import hashlib,json
from pathlib import Path
ROOT=Path(__file__).resolve().parent;raw=(ROOT/'visual-plan.json').read_bytes();p=json.loads(raw);q=json.loads((ROOT/'qa-results.json').read_text());lines=[]
def w(s=''):lines.append(s)
def time(f):return f'{int(f//1800):02}:{(f%1800)/30:06.3f}'
def fmt(o):
 k=o['kind']
 if k=='text':return f"Text **{o['text']}**, center ({o['x']}, {o['y']}), {o['size']} px, color `{o['color']}`"+(f", inside `{o['container']}`" if o.get('container') else '')
 if k=='circle':return f"Circle center ({o['x']}, {o['y']}), radius {o['radius']}, fill `{o['fill']}`, stroke `{o['stroke']}` {o['stroke_width']} px"
 if k=='rect':return f"Rounded rectangle at ({o['x']}, {o['y']}), {o['w']} × {o['h']}, radius {o['radius']}, fill `{o['fill']}`, stroke `{o['stroke']}` {o['stroke_width']} px"
 return f"Line ({o['x1']}, {o['y1']}) → ({o['x2']}, {o['y2']}), `{o['color']}`, {o['stroke_width']} px"
w('# Why is the dollar a world currency?')
w('## A new 60-second code-only Director script')
w('')
w('### Brief and assumptions')
w('- **Confirmed:** A one-minute script explaining the dollar’s international role. All video visuals must be created in code; no image or video inputs.')
w('- **Proposed, not confirmed:** A general English-speaking audience; 1080 × 1920 portrait, 30 fps, exactly 1,800 visual frames; social/video feed placement. Specific platform, overlay boundaries and voice are unconfirmed.')
w('- **Promise:** Explain how history, market depth and reinforcing use support the dollar’s international role. State that it is a leading currency, not the only one, and that its position may change.')
w('- **Audience journey:** Ask why two parties might use someone else’s currency; establish the system’s historical foundations; explain what survived after gold conversion was suspended; show a growing illustrative network; return to the same two parties and directly answer the opening.')
w('- **Hook options:** A: “Why might two countries trade in dollars when neither one issues them?” B: “The dollar’s gold conversion was suspended. Why did its global role continue?” **Recommended: A**, because the final scene can answer the same question with the same two parties. This is a creative judgment, not a tested retention result.')
w('')
w('## Exact voiceover')
for s in p['scenes']:w('\n> '+s['voiceover'])
w('')
w(f"The draft contains about {q['estimated_word_tokens']} word tokens. Numerals and initials can take longer to say. No voice has been recorded, so natural speaking rate, scene boundaries and the final 60-second mix remain unverified.")
w('')
w('## Non-negotiable rules')
w('1. **No visual image or video inputs.** No photographs, screenshots, footage, still-image files, generated-image assets, textures or imported SVG illustrations. Draw all visuals using text, solid colors, circles, rounded rectangles and lines in code. Licensed font files are allowed. The contact sheet is a test output, not an input asset.')
w('2. **No invented facts or data.** Countries A and B are hypothetical. Currency symbols and network nodes are illustrative examples—not exhaustive, not real trades, and not scaled to statistics. The growing network is an explanatory model, not empirical proof that a particular person benefited.')
w('3. **One-minute visual timeline:** 0-based, 30 fps; frames 0–1799 inclusive; intervals `[start,end)`. Exactly 1,800 planned frames under the proposed format. A recorded voice track has not been timed; caption and VO cue timings are provisional.')
w('4. **Determinism:** Derive state from the frame, plan, font and fixed render configuration. No wall-clock timing, unseeded randomness or history-dependent playback. The font is DejaVu Sans Bold; substitute only with approval and repeat layout checks.')
w('5. **Exact dependency:** The complete `visual-plan.json` is embedded at the end of this file and is also supplied separately. It contains every shape, motion, caption cue, group, layer, camera, color and coordinate. Keep the copies identical; no missing authoritative manifest.')
w('6. **Review before delivery:** Do not claim sound synchronization, platform-safe placement, full visual quality, accessibility compliance or audience engagement unless the corresponding output and evidence have actually been inspected.')
w('')
w('## Scene plan and camera')
w('All scenes use a virtual, front-facing **orthographic camera** with pitch, yaw and roll all `0°`. Both viewport center and intentional zoom anchor are `(540,960)`; no physical camera, footage or 3D scene is used. Zoom applies to world graphics only; headings, subheadings and captions are screen-fixed.')
w('| Scene | Time | Frames `[start,end)` | World-camera zoom | Creative purpose |')
w('|---|---|---|---|---|')
for s in p['scenes']:
 cam=s['camera'];w(f"| {s['id']} | {time(s['start'])}–{time(s['end'])} | [{s['start']}, {s['end']}) | {cam['zoom_start']:.3f} → {cam['zoom_end']:.3f} | {s['purpose']} |")
w('')
w('## Per-frame construction contract')
w('For frame `f`, select its single scene, then set `local = f − scene.start` and `D = scene.end − scene.start`. `smooth(x)=u²(3−2u)`, with `u=clamp(x,0,1)`. Coordinates use a top-left origin; rectangles use top-left positions, while text and circles use centers. All units are pixels.')
w('')
w('- Background: fill `night #101B2B`. Colors: `panel #1C2D40`, `ivory #F7F4EC`, `muted #C3CED7`, `gold #EAC777`, `line #96AABB`.')
w('- Each object has an explicit delay and `screen` or `world` group. Compute entry opacity `smooth((local−delay)/18)`. If `fade_out=[a,b]`, multiply opacity by `1−smooth((local−a)/(b−a))`. There is no entry-position shift. Screen headings and subheadings use delay 0 and no camera transform.')
w('- World camera: `z=z0+(z1−z0)×smooth(local/(D−1))`; transform `(x,y)` to `(540+(x−540)×z, 960+(y−960)×z)`. Scale world radii, sizes, stroke widths and font sizes by `z`. Round raster text size and stroke width to the nearest pixel.')
w('- If an object has `move_x`, set its pre-camera x to `from+(to−from)×smooth((local−local_start)/(local_end−local_start))`. Otherwise its base position is held. In scene 1, token and `$` travel together from x=365 to x=715 over local frames 18–120. The token radius is 50 and country radius 70; at each end it touches the respective country’s edge rather than stopping short.')
w('- Draw background, then world objects in their listed order, then screen objects, then captions, using source-over alpha. Network lines are drawn underneath nodes; entry fades have no position shift so endpoints remain attached.')
w('- Captions use a fixed rounded panel at `(70,1510)`, `940 × 180`, radius 22, panel fill. Use 42 px ivory DejaVu Sans Bold: one-line pages centered at `(540,1600)`; two-line pages at `(540,1568)` and `(540,1635)`. **Platform-safe area: NOT VERIFIED.** Caption copy and provisional intervals are specified below, but cue timing is not aligned to any recording.')
w('')
w('## Scene-by-scene production directions')
w('Base positions below are transformed by the per-frame contract. Objects inside their labeled containers are intentional. Scene 7 is a conceptual model: a new participant and new connections appear later; it illustrates a possible reinforcing mechanism, not a measured result.')
for s in p['scenes']:
 w(f"\n### {s['id']} — frames [{s['start']}, {s['end']})")
 w(f"**Purpose:** {s['purpose']}\n")
 w(f"**Voiceover:** “{s['voiceover']}”\n")
 w('| Object | Base geometry and styling | Group / timing |')
 w('|---|---|---|')
 for o in s['objects']:
  t=[o['group'],f"delay {o['delay']}"]
  if 'move_x' in o:
   m=o['move_x'];t.append(f"x {m['from']}→{m['to']} at local {m['local_start']}–{m['local_end']}")
  if 'fade_out' in o:t.append(f"fade-out local {o['fade_out'][0]}–{o['fade_out'][1]}")
  w(f"| {o['id']} | {fmt(o)} | {'; '.join(t)} |")
 w('\n**Draft caption pages; real audio alignment is pending:**')
 for c in s['captions']:w(f"- Frames `[{c['start']}, {c['end']})`: "+' / '.join('“'+x+'”' for x in c['lines']))
w('')
w('## Audio and accessibility')
w('- One clear, conversational narrator. Record the exact script and revise timing around the recording. Do not speed up speech solely to hit a frame number; rebalance scenes while preserving the final agreed duration.')
w('- Optional original or licensed low-level music can support the voice; none is required or supplied. Add meaningful non-speech audio to captions where appropriate. Provide visual description or a descriptive transcript for important visuals not conveyed in audio.')
w('- Perform an actual playback, listening, caption-alignment, device-size readability and platform-overlay review before delivery. These checks have not been performed here.')
w('')
w('## Test report — narrow scope')
w('- **PASS: visual timeline math.** Eight non-overlapping scene intervals cover frames 0–1799 at the proposed 30 fps: 60 seconds of planned visuals.')
w('- **PASS: selected all-frame geometry.** On all 1,800 planned frames, code checked project bounds, text-to-text bounding boxes, selected text containment in both rectangular and circular containers, and caption coverage/bounds. It checked token edge contact at the two stated endpoints and network line endpoints against their nodes. This is not a complete all-object collision or playback test.')
w('- **PASS: exact draft caption text.** The planned caption pages concatenate to the narration. Their timing is not verified against speech.')
w('- **PASS: declared fully opaque text/background pairs only.** Ratios: '+ '; '.join(f'{k}: {v}:1' for k,v in q['nominal_text_background_pairs'].items()) + '. These calculations do not cover partially transparent/composited animation frames, non-text graphics, actual device readability, or overall accessibility compliance.')
w('- **PASS: visual input restriction.** The manifest uses only programmatic text, circles, rectangles and lines. The QA contact sheet is generated from these primitives and is not a video input.')
w('- **NOT CHECKED:** finished video, full-motion playback, narration length, audio/caption synchronization, platform UI overlays, real-device legibility, independent factual review, viewer comprehension or retention.')
w('')
w('## Sources and scope')
w('- [Federal Reserve: International Role of the U.S. Dollar (2025)](https://www.federalreserve.gov/econres/notes/feds-notes/the-international-role-of-the-u-s-dollar-2025-edition-20250718.html): role of economic scale and deep financial markets; the dollar had an international role before 1944.')
w('- [IMF: Central Banks and the Bretton Woods Gold Puzzle](https://www.imf.org/-/media/files/publications/wp/2019/wpiea2019161.pdf): 1944 Bretton Woods framework and the U.S. gold-conversion commitment to other central banks.')
w('- [U.S. State Department: Nixon and the End of Bretton Woods](https://history.state.gov/milestones/1969-1976/nixon-shock): the United States suspended gold convertibility in 1971; the broader fixed-rate system unraveled over 1971–1973.')
w('- [BIS: Global reach of currencies](https://www.bis.org/publ/qtrpdf/r_qt2406b.htm) and [BIS: foreign-exchange markets](https://www.bis.org/publications/qr-202212/global-foreign-exchange-market-higher-volatility-environment): the dollar’s international financial role and trade invoicing.')
w('- [IMF: The Dollar’s Primacy](https://www.imf.org/en/publications/fandd/issues/2022/03/book-review-dollar-primacy-joyce): market liquidity and network effects. The drawn network is an illustration, not causal or quantitative evidence.')
w('')
w('## Embedded complete visual-plan.json')
w('This is the full [separate visual-plan.json](visual-plan.json). The SHA-256 below is computed on the **actual separate UTF-8 file bytes**, including its final LF newline. To reconstruct those bytes from the fenced block, take the block content without the fence delimiter and append one LF. Do not use semantic JSON equality as proof of byte equality.')
w('')
w('File SHA-256: `'+hashlib.sha256(raw).hexdigest()+'`.')
w('```json');w(raw.decode('utf-8').removesuffix('\n'));w('```')
(ROOT/'director-script.md').write_text('\n'.join(lines)+'\n',encoding='utf-8')
print('Created self-contained Director script')
